// Simulation: erase returns the next iterator; wrap manually at end().
int josephusSim(int n, int k) {
    list<int> lst;
    for (int i = 0; i < n; ++i) lst.push_back(i);
    auto it = lst.begin();
    while (lst.size() > 1) {
        for (int step = 1; step < k; ++step) {
            ++it;
            if (it == lst.end()) it = lst.begin();     // wrap
        }
        it = lst.erase(it);                            // erase returns the successor
        if (it == lst.end()) it = lst.begin();
    }
    return *lst.begin();
}

// Recurrence: after the first elimination the problem is the same with n-1
// people, renumbered so that the survivor index shifts by k.
//   J(1) = 0 ;  J(n) = (J(n-1) + k) mod n
int josephusRec(int n, int k) {
    int ans = 0;                       // 0-indexed survivor for n = 1
    for (int m = 2; m <= n; ++m) ans = (ans + k) % m;
    return ans;
}

struct Term { int coeff, exp; Term* next; };

// ADD: LC21 merge with an exponent comparator and coefficient combination.
Term* addPoly(Term* a, Term* b) {
    Term dummy{0,0,nullptr}, *tail = &dummy;
    while (a && b) {
        Term* t;
        if (a->exp > b->exp)      { t = new Term{a->coeff, a->exp, nullptr}; a = a->next; }
        else if (a->exp < b->exp) { t = new Term{b->coeff, b->exp, nullptr}; b = b->next; }
        else {
            int c = a->coeff + b->coeff;
            a = a->next; b = b->next;
            if (c == 0) continue;                  // cancelling terms VANISH
            t = new Term{c, (a ? a->exp : 0), nullptr};
        }
        tail->next = t; tail = t;
    }
    for (Term* r = a ? a : b; r; r = r->next) {
        tail->next = new Term{r->coeff, r->exp, nullptr}; tail = tail->next;
    }
    return dummy.next;
}

