def add_poly(a: list, b: list) -> list:
    """Terms are (coeff, exp) sorted by exp DESCENDING. Merge with combine."""
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i][1] > b[j][1]:
            out.append(a[i]); i += 1
        elif a[i][1] < b[j][1]:
            out.append(b[j]); j += 1
        else:
            c = a[i][0] + b[j][0]
            if c:                          # cancelling terms VANISH
                out.append((c, a[i][1]))
            i += 1; j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out


def mul_poly(a: list, b: list) -> list:
    """Accumulate products by exponent, then emit in descending order."""
    acc = {}
    for ca, ea in a:
        for cb, eb in b:
            acc[ea + eb] = acc.get(ea + eb, 0) + ca * cb
    return [(c, e) for e, c in sorted(acc.items(), key=lambda kv: -kv[0]) if c]

