def list_merge_sort(values: list) -> list:
    """Bottom-up merge sort, the shape std::list::merge implements by splicing.

    In C++ each merge is O(1) per node (pointers move, elements do not).
    Python lists are arrays, so this is a faithful ALGORITHM demo, not a
    faithful performance demo -- see the C++ comment for the real numbers."""
    runs = []
    for v in values:
        carry = [v]
        level = 0
        while level < len(runs) and runs[level]:
            carry = _merge_sorted(runs[level], carry)
            runs[level] = []
            level += 1
        if level == len(runs):
            runs.append([])
        runs[level] = carry
    out = []
    for r in runs:
        out = _merge_sorted(out, r)
    return out


def _merge_sorted(a: list, b: list) -> list:
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

