struct SkipList {
    static const int MAXLEVEL = 20;
    struct Node { int key; vector<Node*> next; Node(int k, int h) : key(k), next(h, nullptr) {} };
    Node* head = new Node(INT_MIN, MAXLEVEL);
    int level = 1;
    mt19937 rng{random_device{}()};

    // height = 1 + number of consecutive heads. P(height >= h) = 2^-(h-1).
    int randomHeight() {
        int h = 1;
        while (h < MAXLEVEL && (rng() & 1)) ++h;
        return h;
    }
    // fills update[i] with the last node at level i that precedes key
    Node* findPredecessors(int key, vector<Node*>& update) {
        Node* cur = head;
        for (int i = level - 1; i >= 0; --i) {
            while (cur->next[i] && cur->next[i]->key < key) cur = cur->next[i];
            update[i] = cur;
        }
        return cur->next[0];
    }
    bool search(int key) {
        vector<Node*> update(MAXLEVEL);
        Node* c = findPredecessors(key, update);
        return c && c->key == key;
    }
    void insert(int key) {
        vector<Node*> update(MAXLEVEL, head);
        Node* c = findPredecessors(key, update);
        if (c && c->key == key) return;                 // set semantics: no duplicates
        int h = randomHeight();
        if (h > level) { for (int i = level; i < h; ++i) update[i] = head; level = h; }
        Node* node = new Node(key, h);
        for (int i = 0; i < h; ++i) {                   // splice in at EVERY level
            node->next[i] = update[i]->next[i];
            update[i]->next[i] = node;
        }
    }
    void erase(int key) {
        vector<Node*> update(MAXLEVEL, head);
        Node* c = findPredecessors(key, update);
        if (!c || c->key != key) return;
        for (int i = 0; i < level; ++i)
            if (update[i]->next[i] == c) update[i]->next[i] = c->next[i];
        while (level > 1 && !head->next[level - 1]) --level;   // shrink empty top levels
        delete c;
    }
};

