import random as _rnd


class SkipList:
    MAXLEVEL = 20

    class Node:
        __slots__ = ("key", "next")
        def __init__(self, key, height):
            self.key = key
            self.next = [None] * height

    def __init__(self, seed=None):
        self.head = SkipList.Node(None, SkipList.MAXLEVEL)
        self.level = 1
        self.rng = _rnd.Random(seed)

    def _random_height(self) -> int:
        """height = 1 + consecutive heads. P(height >= h) = 2^-(h-1)."""
        h = 1
        while h < SkipList.MAXLEVEL and self.rng.getrandbits(1):
            h += 1
        return h

    def _predecessors(self, key):
        """update[i] = last node at level i preceding key."""
        update = [self.head] * SkipList.MAXLEVEL
        cur = self.head
        for i in range(self.level - 1, -1, -1):
            while cur.next[i] is not None and cur.next[i].key < key:
                cur = cur.next[i]
            update[i] = cur
        return cur.next[0], update

    def search(self, key) -> bool:
        c, _ = self._predecessors(key)
        return c is not None and c.key == key

    def insert(self, key) -> None:
        c, update = self._predecessors(key)
        if c is not None and c.key == key:
            return                              # set semantics: no duplicates
        h = self._random_height()
        if h > self.level:
            self.level = h
        node = SkipList.Node(key, h)
        for i in range(h):                      # splice in at EVERY level
            node.next[i] = update[i].next[i]
            update[i].next[i] = node

    def erase(self, key) -> None:
        c, update = self._predecessors(key)
        if c is None or c.key != key:
            return
        for i in range(self.level):
            if update[i].next[i] is c:
                update[i].next[i] = c.next[i]
        while self.level > 1 and self.head.next[self.level - 1] is None:
            self.level -= 1                     # shrink empty top levels

    def to_list(self) -> list:
        out, t = [], self.head.next[0]
        while t:
            out.append(t.key); t = t.next[0]
        return out

