class LRUCache {
    int cap;
    list<int> order;                                  // front = most recent
    unordered_map<int, pair<int, list<int>::iterator>> table;   // key -> (value, position)
public:
    explicit LRUCache(int capacity) : cap(capacity) {}

    int get(int key) {
        auto it = table.find(key);
        if (it == table.end()) return -1;
        // splice moves the node to the front WITHOUT allocating or invalidating it
        order.splice(order.begin(), order, it->second.second);
        return it->second.first;
    }
    void put(int key, int value) {
        auto it = table.find(key);
        if (it != table.end()) {
            it->second.first = value;
            order.splice(order.begin(), order, it->second.second);
            return;
        }
        if ((int)table.size() == cap) {
            table.erase(order.back());                // evict the least recent
            order.pop_back();
        }
        order.push_front(key);
        table[key] = {value, order.begin()};
    }
};

