class LRUCache:
    """Python's OrderedDict provides the same O(1) move-to-end that
    std::list::splice does; the underlying structure is a doubly linked list
    with a hash index -- exactly the C++ design."""

    def __init__(self, capacity: int):
        from collections import OrderedDict
        self.cap = capacity
        self.data = OrderedDict()

    def get(self, key: int) -> int:
        if key not in self.data:
            return -1
        self.data.move_to_end(key)          # O(1) relink, no reallocation
        return self.data[key]

    def put(self, key: int, value: int) -> None:
        if key in self.data:
            self.data[key] = value
            self.data.move_to_end(key)
            return
        if len(self.data) == self.cap:
            self.data.popitem(last=False)   # evict the least recent
        self.data[key] = value

