// STRUCTURE SELECTION ARGUMENT (this problem grades the defense, not the code).
//
// Operation frequencies in a real editor, per minute of typing:
//   cursor moves within a line   ~thousands   (arrow keys, mouse)
//   inserts/deletes at cursor    ~hundreds
//   line insert/delete           ~tens
//   jumps to a far offset        ~a few
//
// GAP BUFFER  -- one array with a movable hole at the cursor.
//   + insert/delete at the cursor are O(1) amortised, and the data is contiguous,
//     so rendering and search stream at memory bandwidth.
//   - moving the cursor far costs O(distance) because the gap must be memmoved.
//   Real users type in bursts at one location, so the gap rarely moves far.
//   Used by: Emacs.
//
// PIECE TABLE -- original buffer is IMMUTABLE; an ordered list of (buffer, start,
//   len) pieces describes the current document; edits append to a second buffer.
//   + edits never move existing text, so undo is just restoring the piece list.
//   + memory-mapping the original file costs nothing to open.
//   - reading offset i requires walking pieces, so an index is needed for O(log n).
//   Used by: VS Code, and Microsoft Word historically.
//
// LINKED LINES -- a list of lines, each a small string or gap buffer.
//   + line insert/delete/reorder is an O(1) splice; line numbers are natural.
//   - cursor movement within a long line is O(line length) and cache-hostile;
//     one node per line is a pointer chase per line during a full-document scan.
//
// VERDICT for a 10^6-character document: piece table. Its costs land on the RARE
// operations (random offset lookup) and its wins land on the FREQUENT ones
// (localised edits, instant undo, zero-copy file open). A gap buffer is the right
// answer if undo is not required and the document is edited in one place.

struct Piece { int buffer; int start; int len; };   // buffer: 0 = original, 1 = added

struct PieceTable {
    string original, added;
    vector<Piece> pieces;

    explicit PieceTable(string text) : original(move(text)) {
        if (!original.empty()) pieces.push_back({0, 0, (int)original.size()});
    }
    // O(pieces) here; a balanced tree over cumulative lengths makes it O(log n)
    void insert(int offset, const string& text) {
        int addStart = (int)added.size();
        added += text;
        Piece fresh{1, addStart, (int)text.size()};
        int walked = 0;
        for (size_t i = 0; i < pieces.size(); ++i) {
            if (walked + pieces[i].len >= offset) {
                int split = offset - walked;
                Piece left{pieces[i].buffer, pieces[i].start, split};
                Piece right{pieces[i].buffer, pieces[i].start + split, pieces[i].len - split};
                pieces.erase(pieces.begin() + i);
                vector<Piece> ins;
                if (left.len)  ins.push_back(left);
                ins.push_back(fresh);
                if (right.len) ins.push_back(right);
                pieces.insert(pieces.begin() + i, ins.begin(), ins.end());
                return;
            }
            walked += pieces[i].len;
        }
        pieces.push_back(fresh);
    }
    string text() const {
        string out;
        for (const Piece& p : pieces)
            out += (p.buffer == 0 ? original : added).substr(p.start, p.len);
        return out;
    }
};
